import { GBNF } from '/workspace/reference_implementation/src/index.js';

const CASES: [string, string][] = [
  ['root ::= "foo', ''],
  ['root ::= [a-z', ''],
  ['root ::= "\\t"', '\t'],
  ['root ::= "\\u0041"', 'A'],
  ['root ::= "\\x41"', 'A'],
  ['root ::= "\\\\"', '\\'],
  ['root ::= "\\xZZ"', ''],
  ['root ::= "\\q"', ''],
  ['foo ::= "bar"', ''],
  ['root ::= ', ''],
  ['root ::=', ''],
  ['root ::= "a" # comment\n', 'a'],
  ['# only a comment', ''],
  ['root ::= [a-]', '-'],
  ['root ::= [^]', ''],
  ['root ::= ()', ''],
  ['root ::= *', ''],
  ['root ::= "a"|', 'a'],
  ['root ::= "a" "b"', 'ab'],
  ['root-1 ::= "a"\nroot ::= root-1', 'a'],
  ['root ::= "é"', 'é'],
  ['root ::= [\\x00-\\x7F]', 'q'],
];

